# key: (法令名, 条番号, 見出し, 本文)  ※令和8年11月時点の現行法（拘禁刑施行後）として記載。長い条文は抄。
A = {
"刑38": ("刑法","38条1項・3項","故意","1　罪を犯す意思がない行為は、罰しない。ただし、法律に特別の規定がある場合は、この限りでない。<br>3　法律を知らなかったとしても、そのことによって、罪を犯す意思がなかったとすることはできない。ただし、情状により、その刑を減軽することができる。"),
"刑43": ("刑法","43条","未遂減免","犯罪の実行に着手してこれを遂げなかった者は、その刑を減軽することができる。ただし、<mark>自己の意思により</mark>犯罪を中止したときは、その刑を減軽し、又は免除する。"),
"刑54": ("刑法","54条1項","一個の行為が二個以上の罪名に触れる場合等の処理","<mark>一個の行為が二個以上の罪名に触れ</mark>、又は犯罪の手段若しくは結果である行為が他の罪名に触れるときは、その最も重い刑により処断する。"),
"刑60": ("刑法","60条","共同正犯","二人以上共同して犯罪を実行した者は、すべて正犯とする。"),
"刑61": ("刑法","61条1項","教唆","人を教唆して犯罪を実行させた者には、正犯の刑を科する。"),
"刑65": ("刑法","65条","身分犯の共犯","1　<mark>犯人の身分によって構成すべき犯罪行為</mark>に加功したときは、身分のない者であっても、共犯とする。<br>2　<mark>身分によって特に刑の軽重があるとき</mark>は、身分のない者には通常の刑を科する。"),
"刑95": ("刑法","95条1項","公務執行妨害","公務員が職務を執行するに当たり、これに対して暴行又は脅迫を加えた者は、三年以下の拘禁刑又は五十万円以下の罰金に処する。"),
"刑103": ("刑法","103条","犯人蔵匿等","罰金以上の刑に当たる罪を犯した者又は拘禁中に逃走した者を蔵匿し、又は<mark>隠避させた者</mark>は、三年以下の拘禁刑又は三十万円以下の罰金に処する。"),
"刑104": ("刑法","104条","証拠隠滅等","<mark>他人の刑事事件</mark>に関する証拠を隠滅し、<mark>偽造し</mark>、若しくは変造し、又は偽造若しくは変造の証拠を使用した者は、三年以下の拘禁刑又は三十万円以下の罰金に処する。"),
"刑108": ("刑法","108条","現住建造物等放火","放火して、<mark>現に人が住居に使用し又は現に人がいる</mark>建造物、汽車、電車、艦船又は鉱坑を焼損した者は、死刑又は無期若しくは五年以上の拘禁刑に処する。"),
"刑109": ("刑法","109条","非現住建造物等放火","1　放火して、現に人が住居に使用せず、かつ、現に人がいない建造物、艦船又は鉱坑を焼損した者は、二年以上の有期拘禁刑に処する。<br>2　前項の物が<mark>自己の所有に係るとき</mark>は、六月以上七年以下の拘禁刑に処する。ただし、<mark>公共の危険を生じなかったときは、罰しない</mark>。"),
"刑112": ("刑法","112条","未遂罪","第百八条及び第百九条第一項の罪の未遂は、罰する。"),
"刑113": ("刑法","113条","予備","第百八条又は第百九条第一項の罪を犯す目的で、その予備をした者は、二年以下の拘禁刑に処する。ただし、情状により、その刑を免除することができる。"),
"刑115": ("刑法","115条","差押え等に係る自己の物に関する特例","第百九条第一項及び第百十条第一項に規定する物が自己の所有に係るものであっても、差押えを受け、物権を負担し、賃貸し、配偶者居住権が設定され、又は<mark>保険に付したもの</mark>である場合において、これを焼損したときは、<mark>他人の物を焼損した者の例による</mark>。"),
"刑130": ("刑法","130条","住居侵入等","正当な理由がないのに、人の住居若しくは人の看守する邸宅、建造物若しくは艦船に<mark>侵入し</mark>、又は要求を受けたにもかかわらずこれらの場所から退去しなかった者は、三年以下の拘禁刑又は十万円以下の罰金に処する。"),
"刑169": ("刑法","169条","偽証","<mark>法律により宣誓した証人</mark>が虚偽の陳述をしたときは、三月以上十年以下の拘禁刑に処する。"),
"刑199": ("刑法","199条","殺人","人を殺した者は、死刑又は無期若しくは五年以上の拘禁刑に処する。"),
"刑202": ("刑法","202条","自殺関与及び同意殺人","人を教唆し若しくは幇助して自殺させ、又は人をその嘱託を受け若しくはその承諾を得て殺した者は、六月以上七年以下の拘禁刑に処する。"),
"刑203": ("刑法","203条","未遂罪","第百九十九条及び前条の罪の未遂は、罰する。"),
"刑204": ("刑法","204条","傷害","人の身体を傷害した者は、十五年以下の拘禁刑又は五十万円以下の罰金に処する。"),
"刑207": ("刑法","207条","同時傷害の特例","二人以上で暴行を加えて人を傷害した場合において、それぞれの暴行による傷害の軽重を知ることができず、又はその傷害を生じさせた者を知ることができないときは、<mark>共同して実行した者でなくても、共犯の例による</mark>。"),
"刑210": ("刑法","210条","過失致死","過失により人を死亡させた者は、五十万円以下の罰金に処する。"),
"刑217": ("刑法","217条","遺棄","老年、幼年、身体障害又は疾病のために扶助を必要とする者を遺棄した者は、一年以下の拘禁刑に処する。"),
"刑218": ("刑法","218条","保護責任者遺棄等","老年者、幼年者、身体障害者又は病者を<mark>保護する責任のある者</mark>がこれらの者を遺棄し、又はその生存に必要な保護をしなかったときは、三月以上五年以下の拘禁刑に処する。"),
"刑219": ("刑法","219条","遺棄等致死傷","前二条の罪を犯し、よって人を死傷させた者は、傷害の罪と比較して、重い刑により処断する。"),
"刑235": ("刑法","235条","窃盗","他人の財物を<mark>窃取</mark>した者は、窃盗の罪とし、十年以下の拘禁刑又は五十万円以下の罰金に処する。"),
"刑236": ("刑法","236条","強盗","1　暴行又は脅迫を用いて他人の財物を強取した者は、強盗の罪とし、五年以上の有期拘禁刑に処する。<br>2　前項の方法により、<mark>財産上不法の利益を得</mark>、又は他人にこれを得させた者も、同項と同様とする。"),
"刑238": ("刑法","238条","事後強盗","窃盗が、<mark>財物を得てこれを取り返されることを防ぎ、逮捕を免れ、又は罪跡を隠滅するために</mark>、暴行又は脅迫をしたときは、強盗として論ずる。"),
"刑240": ("刑法","240条","強盗致死傷","強盗が、人を負傷させたときは無期又は六年以上の拘禁刑に処し、死亡させたときは死刑又は無期拘禁刑に処する。"),
"刑242": ("刑法","242条","他人の占有等に係る自己の財物","<mark>自己の財物であっても、他人が占有し</mark>、又は公務所の命令により他人が看守するものであるときは、この章の罪については、<mark>他人の財物とみなす</mark>。"),
"刑244": ("刑法","244条","親族間の犯罪に関する特例","1　配偶者、直系血族又は同居の親族との間で第二百三十五条の罪、第二百三十五条の二の罪又はこれらの罪の未遂罪を犯した者は、<mark>その刑を免除する</mark>。<br>2　前項に規定する親族以外の親族との間で犯した同項に規定する罪は、告訴がなければ公訴を提起することができない。<br>3　前二項の規定は、親族でない共犯については、適用しない。"),
"刑246": ("刑法","246条","詐欺","1　人を欺いて財物を交付させた者は、十年以下の拘禁刑に処する。<br>2　前項の方法により、財産上不法の利益を得、又は他人にこれを得させた者も、同項と同様とする。"),
"刑249": ("刑法","249条","恐喝","1　人を恐喝して財物を交付させた者は、十年以下の拘禁刑に処する。<br>2　前項の方法により、財産上不法の利益を得、又は他人にこれを得させた者も、同項と同様とする。"),
"刑252": ("刑法","252条1項","横領","<mark>自己の占有する他人の物</mark>を横領した者は、五年以下の拘禁刑に処する。"),
"刑253": ("刑法","253条","業務上横領","<mark>業務上</mark>自己の占有する他人の物を横領した者は、十年以下の拘禁刑に処する。"),
"刑254": ("刑法","254条","遺失物等横領","遺失物、漂流物その他<mark>占有を離れた他人の物</mark>を横領した者は、一年以下の拘禁刑又は十万円以下の罰金若しくは科料に処する。"),
"刑256": ("刑法","256条2項","盗品譲受け等","前項に規定する物を運搬し、<mark>保管し</mark>、若しくは有償で譲り受け、又はその有償の処分のあっせんをした者は、十年以下の拘禁刑及び五十万円以下の罰金に処する。"),
"憲37": ("憲法","37条1項・2項","","1　すべて刑事事件においては、被告人は、<mark>公平な裁判所</mark>の迅速な公開裁判を受ける権利を有する。<br>2　刑事被告人は、すべての証人に対して<mark>審問する機会を充分に与へられ</mark>、又、公費で自己のために強制的手続により証人を求める権利を有する。"),
"憲38": ("憲法","38条1項","","何人も、自己に不利益な供述を強要されない。"),
"憲82": ("憲法","82条1項","","裁判の対審及び判決は、公開法廷でこれを行ふ。"),
"警職2": ("警職法","2条1項","質問","警察官は、異常な挙動その他周囲の事情から合理的に判断して何らかの犯罪を犯し、若しくは犯そうとしていると<mark>疑うに足りる相当な理由のある者</mark>又は既に行われた犯罪について、若しくは犯罪が行われようとしていることについて知つていると認められる者を<mark>停止させて質問することができる</mark>。"),
"訴39": ("刑訴法","39条1項","接見交通権","身体の拘束を受けている被告人又は被疑者は、弁護人又は弁護人を選任することができる者の依頼により弁護人となろうとする者（弁護士でない者にあつては、第三十一条第二項の許可があつた後に限る。）と<mark>立会人なくして接見</mark>し、又は書類若しくは物の授受をすることができる。"),
"訴60": ("刑訴法","60条","勾留の理由・期間","1　裁判所は、被告人が罪を犯したことを疑うに足りる相当な理由がある場合で、左の各号の一にあたるときは、これを勾留することができる。<br>一　被告人が定まつた住居を有しないとき。<br>二　被告人が罪証を隠滅すると疑うに足りる相当な理由があるとき。<br>三　被告人が逃亡し又は逃亡すると疑うに足りる相当な理由があるとき。<br>2　勾留の期間は、<mark>公訴の提起があつた日から二箇月</mark>とする。特に継続の必要がある場合においては、具体的にその理由を附した決定で、<mark>一箇月ごとにこれを更新</mark>することができる。（ただし書略）"),
"訴61": ("刑訴法","61条","勾留と被告事件の告知","被告人の勾留は、被告人に対し被告事件を告げこれに関する陳述を聴いた後でなければ、これをすることができない。但し、被告人が逃亡した場合は、この限りでない。（被疑者の勾留には207条1項で準用）"),
"訴73": ("刑訴法","73条3項","令状を所持しない場合の執行（緊急執行）","勾引状又は勾留状を所持しないためこれを示すことができない場合において、<mark>急速を要するとき</mark>は、前二項の規定にかかわらず被告人に対して<mark>公訴事実の要旨及び令状が発せられている旨を告げて</mark>、その執行をすることができる。但し、令状は、<mark>できる限り速やかにこれを示さなければならない</mark>。"),
"訴81": ("刑訴法","81条","接見等の禁止","裁判所は、逃亡し又は罪証を隠滅すると疑うに足りる相当な理由があるときは、検察官の請求により又は職権で、勾留されている被告人と<mark>第三十九条第一項に規定する者以外の者</mark>との接見を禁じ、又はこれと授受すべき書類その他の物を検閲し、その授受を禁じ、若しくはこれを差し押えることができる。但し、糧食の授受を禁じ、又はこれを差し押えることはできない。"),
"訴87": ("刑訴法","87条1項","勾留の取消し","勾留の理由又は勾留の必要がなくなつたときは、裁判所は、検察官、勾留されている被告人若しくはその弁護人、法定代理人、保佐人、配偶者、直系の親族若しくは兄弟姉妹の請求により、又は職権で、決定を以て勾留を取り消さなければならない。"),
"訴111": ("刑訴法","111条","押収・捜索と必要な処分","1　差押状、記録命令付差押状又は捜索状の執行については、<mark>錠をはずし、封を開き、その他必要な処分</mark>をすることができる。公判廷で差押え、記録命令付差押え又は捜索をする場合も、同様である。<br>2　前項の処分は、<mark>押収物についても</mark>、これをすることができる。（捜査機関には222条1項で準用）"),
"訴111-2": ("刑訴法","111条の2","電磁的記録の差押えと協力要請","差し押さえるべき物が電磁的記録に係る記録媒体であるときは、差押状又は捜索状の執行をする者は、処分を受ける者に対し、<mark>電子計算機の操作その他の必要な協力を求める</mark>ことができる。公判廷で差押え又は捜索をする場合も、同様である。"),
"訴146": ("刑訴法","146条","自己の刑事責任と証言拒絶権","何人も、自己が刑事訴追を受け、又は有罪判決を受ける虞のある証言を拒むことができる。"),
"訴147": ("刑訴法","147条","近親者の刑事責任と証言拒絶権","何人も、左に掲げる者が刑事訴追を受け、又は有罪判決を受ける虞のある証言を拒むことができる。<br>一　自己の配偶者、三親等内の血族若しくは二親等内の姻族又は自己とこれらの親族関係があつた者<br>二　自己の後見人、後見監督人又は保佐人<br>三　自己を後見人、後見監督人又は保佐人とする者"),
"訴149": ("刑訴法","149条","業務上秘密と証言拒絶権","医師、歯科医師、助産師、看護師、弁護士（外国法事務弁護士を含む。）、弁理士、公証人、宗教の職に在る者又はこれらの職に在つた者は、業務上委託を受けたため知り得た事実で他人の秘密に関するものについては、証言を拒むことができる。（ただし書略）"),
"訴157-4": ("刑訴法","157条の4","証人への付添い","1　裁判所は、証人を尋問する場合において、証人の年齢、心身の状態その他の事情を考慮し、証人が<mark>著しく不安又は緊張を覚えるおそれ</mark>があると認めるときは、検察官及び被告人又は弁護人の意見を聴き、その不安又は緊張を緩和するのに適当であり、かつ、裁判官若しくは訴訟関係人の尋問若しくは証人の供述を妨げ、又はその供述の内容に不当な影響を与えるおそれがないと認める者を、その証人の供述中、証人に付き添わせることができる。<br>2　（付添人の禁止行為。略）"),
"訴157-5": ("刑訴法","157条の5","遮へい措置（抄）","1　裁判所は、証人を尋問する場合において、犯罪の性質、証人の年齢、心身の状態、被告人との関係その他の事情により、証人が<mark>被告人の面前（次条第一項及び第二項に規定する方法による場合を含む。）</mark>において供述するときは圧迫を受け精神の平穏を著しく害されるおそれがあると認める場合であつて、相当と認めるときは、検察官及び被告人又は弁護人の意見を聴き、被告人とその証人との間で、一方から又は相互に相手の状態を認識することができないようにするための措置を採ることができる。ただし、被告人から証人の状態を認識することができないようにするための措置については、<mark>弁護人が出頭している場合に限り</mark>、採ることができる。<br>2　裁判所は、証人を尋問する場合において、犯罪の性質、証人の年齢、心身の状態、<mark>名誉に対する影響</mark>その他の事情を考慮し、相当と認めるときは、検察官及び被告人又は弁護人の意見を聴き、傍聴人とその証人との間で、相互に相手の状態を認識することができないようにするための措置を採ることができる。"),
"訴197": ("刑訴法","197条1項","任意捜査の原則","捜査については、その目的を達するため必要な取調をすることができる。但し、<mark>強制の処分は、この法律に特別の定のある場合でなければ、これをすることができない</mark>。"),
"訴201": ("刑訴法","201条","逮捕状による逮捕の手続","1　逮捕状により被疑者を逮捕するには、逮捕状を被疑者に示さなければならない。<br>2　<mark>第七十三条第三項の規定は、逮捕状により被疑者を逮捕する場合にこれを準用する</mark>。"),
"訴205": ("刑訴法","205条1項","検察官の勾留請求の時間制限","検察官は、第二百三条の規定により送致された被疑者を受け取つたときは、弁解の機会を与え、留置の必要がないと思料するときは直ちにこれを釈放し、留置の必要があると思料するときは<mark>被疑者を受け取つた時から二十四時間以内</mark>に裁判官に被疑者の勾留を請求しなければならない。（2項以下略）"),
"訴210": ("刑訴法","210条1項","緊急逮捕","検察官、検察事務官又は司法警察職員は、<mark>死刑又は無期若しくは長期三年以上の拘禁刑</mark>にあたる罪を犯したことを<mark>疑うに足りる充分な理由</mark>がある場合で、<mark>急速を要し、裁判官の逮捕状を求めることができないとき</mark>は、その理由を告げて被疑者を逮捕することができる。この場合には、<mark>直ちに裁判官の逮捕状を求める手続</mark>をしなければならない。逮捕状が発せられないときは、直ちに被疑者を釈放しなければならない。"),
"訴212": ("刑訴法","212条","現行犯人・準現行犯人","1　現に罪を行い、又は現に罪を行い終つた者を現行犯人とする。<br>2　左の各号の一にあたる者が、<mark>罪を行い終つてから間がないと明らかに認められるとき</mark>は、これを現行犯人とみなす。<br>一　犯人として追呼されているとき。<br>二　贓物又は明らかに犯罪の用に供したと思われる兇器その他の物を所持しているとき。<br>三　身体又は被服に犯罪の顕著な証跡があるとき。<br>四　誰何されて逃走しようとするとき。"),
"訴218-3": ("刑訴法","218条3項","身体拘束中の被疑者の写真撮影等","身体の拘束を受けている被疑者の指紋若しくは足型を採取し、身長若しくは体重を測定し、又は<mark>写真を撮影</mark>するには、被疑者を裸にしない限り、第一項の令状によることを要しない。"),
"訴218-6": ("刑訴法","218条6項","身体検査の条件","裁判官は、身体の検査に関し、<mark>適当と認める条件を附することができる</mark>。（強制採尿令状では捜索差押許可状にこの規定を準用して条件を記載する。最決昭55.10.23）"),
"訴219": ("刑訴法","99条1項（222条1項で準用）","差押え","裁判所は、必要があるときは、<mark>証拠物又は没収すべき物と思料するもの</mark>を差し押えることができる。但し、特別の定のある場合は、この限りでない。（捜査機関の差押えには222条1項で準用。令状の記載事項は219条1項）"),
"訴220": ("刑訴法","220条1項","令状によらない差押え・捜索・検証","検察官、検察事務官又は司法警察職員は、第百九十九条の規定により被疑者を逮捕する場合又は現行犯人を逮捕する場合において必要があるときは、左の処分をすることができる。第二百十条の規定により被疑者を逮捕する場合において必要があるときも、同様である。<br>一　人の住居又は人の看守する邸宅、建造物若しくは船舶内に入り被疑者の捜索をすること。<br>二　<mark>逮捕の現場で差押、捜索又は検証をすること</mark>。"),
"訴221": ("刑訴法","221条","領置","検察官、検察事務官又は司法警察職員は、<mark>被疑者その他の者が遺留した物</mark>又は所有者、所持者若しくは<mark>保管者が任意に提出した物</mark>は、これを領置することができる。"),
"訴248": ("刑訴法","248条","起訴便宜主義","犯人の性格、年齢及び境遇、犯罪の軽重及び情状並びに犯罪後の情況により訴追を必要としないときは、<mark>公訴を提起しないことができる</mark>。"),
"訴256-6": ("刑訴法","256条6項","起訴状一本主義","起訴状には、裁判官に事件につき<mark>予断を生ぜしめる虞</mark>のある書類その他の物を添附し、又はその内容を引用してはならない。"),
"訴280": ("刑訴法","280条1項","第一回公判期日前の勾留に関する処分","公訴の提起があつた後第一回の公判期日までは、勾留に関する処分は、<mark>裁判官</mark>がこれを行う。"),
"訴290-2": ("刑訴法","290条の2（抄）","公開の法廷での被害者特定事項の秘匿","1　裁判所は、次に掲げる事件を取り扱う場合において、当該事件の被害者等若しくは当該被害者の法定代理人又はこれらの者から委託を受けた弁護士から申出があるときは、<mark>被告人又は弁護人の意見を聴き、相当と認めるとき</mark>は、被害者特定事項（氏名及び住所その他の当該事件の被害者を特定させることとなる事項をいう。以下同じ。）を<mark>公開の法廷で明らかにしない旨の決定</mark>をすることができる。（各号略）<br>2　前項の申出は、<mark>あらかじめ、検察官にしなければならない</mark>。この場合において、検察官は、<mark>意見を付して、これを裁判所に通知する</mark>ものとする。"),
"訴291": ("刑訴法","291条1項","起訴状の朗読","検察官は、まず、起訴状を朗読しなければならない。"),
"訴294": ("刑訴法","294条","訴訟指揮","公判期日における訴訟の指揮は、裁判長がこれを行う。"),
"訴305": ("刑訴法","305条1項","証拠書類の取調べ","検察官、被告人又は弁護人の請求により、証拠書類の取調をするについては、裁判長は、その取調を請求した者にこれを<mark>朗読</mark>させなければならない。但し、裁判長は、自らこれを朗読し、又は陪席の裁判官若しくは裁判所書記官にこれを朗読させることができる。"),
"訴309": ("刑訴法","309条","異議の申立て","1　検察官、被告人又は弁護人は、<mark>証拠調に関し異議を申し立てる</mark>ことができる。<br>2　検察官、被告人又は弁護人は、前項に規定する場合の外、裁判長の処分に対して異議を申し立てることができる。<br>3　裁判所は、前二項の申立について<mark>決定をしなければならない</mark>。"),
"訴311": ("刑訴法","311条","被告人の黙秘権・被告人質問","1　被告人は、<mark>終始沈黙し、又は個々の質問に対し、供述を拒むことができる</mark>。<br>2　被告人が任意に供述をする場合には、裁判長は、何時でも必要とする事項につき被告人の供述を求めることができる。<br>3　陪席の裁判官、検察官、弁護人、<mark>共同被告人又はその弁護人</mark>は、裁判長に告げて、前項の供述を求めることができる。"),
"訴312": ("刑訴法","312条1項・2項","訴因・罰条の変更","1　裁判所は、検察官の請求があるときは、<mark>公訴事実の同一性を害しない限度</mark>において、起訴状に記載された訴因又は罰条の追加、撤回又は変更を許さなければならない。<br>2　裁判所は、審理の経過に鑑み適当と認めるときは、訴因又は罰条を追加又は変更すべきことを命ずることができる。"),
"訴316-15": ("刑訴法","316条の15第1項（抄）","類型証拠の開示","検察官は、前条第一項の規定による開示をした証拠以外の証拠であつて、<mark>次の各号に掲げる証拠の類型のいずれかに該当</mark>し、かつ、<mark>特定の検察官請求証拠の証明力を判断するために重要</mark>であると認められるものについて、被告人又は弁護人から開示の請求があつた場合において、その重要性の程度その他の<mark>被告人の防御の準備のために当該開示をすることの必要性</mark>の程度並びに当該開示によつて生じるおそれのある弊害の内容及び程度を考慮し、相当と認めるときは、速やかに、…開示をしなければならない。（各号、以下略。請求時に明らかにする事項は同条3項）"),
"訴316-16": ("刑訴法","316条の16第1項","検察官請求証拠に対する意見","被告人又は弁護人は、第三百十六条の十三第一項の書面の送付を受け、かつ、第三百十六条の十四第一項並びに前条第一項及び第二項の規定による開示をすべき証拠の開示を受けたときは、検察官請求証拠について、<mark>第三百二十六条の同意をするかどうか又はその取調べの請求に関し異議がないかどうかの意見</mark>を明らかにしなければならない。"),
"訴316-20": ("刑訴法","316条の20第1項（抄）","主張関連証拠の開示","検察官は、第三百十六条の十四第一項並びに第三百十六条の十五第一項及び第二項の規定による開示をした証拠以外の証拠であつて、<mark>第三百十六条の十七第一項の主張に関連する</mark>と認められるものについて、被告人又は弁護人から開示の請求があつた場合において、その関連性の程度その他の被告人の防御の準備のために当該開示をすることの必要性の程度並びに当該開示によつて生じるおそれのある弊害の内容及び程度を考慮し、相当と認めるときは、速やかに、…開示をしなければならない。（以下略）"),
"訴316-26": ("刑訴法","316条の26第1項（抄）","証拠開示命令","裁判所は、検察官が…第三百十六条の十五第一項…若しくは<mark>第三百十六条の二十第一項</mark>…の規定による開示をすべき証拠を開示していないと認めるときは、被告人又は弁護人の請求により、決定で、<mark>当該証拠の開示を命じなければならない</mark>。（以下略）"),
"訴316-30": ("刑訴法","316条の30（抄）","被告人側の冒頭陳述","公判前整理手続に付された事件については、被告人又は弁護人は、証拠により証明すべき事実その他の事実上及び法律上の主張があるときは、第二百九十六条の手続に引き続き、<mark>これを明らかにしなければならない</mark>。（以下略）"),
"訴320": ("刑訴法","320条1項","伝聞法則","第三百二十一条乃至第三百二十八条に規定する場合を除いては、公判期日における供述に代えて書面を証拠とし、又は<mark>公判期日外における他の者の供述を内容とする供述</mark>を証拠とすることはできない。"),
"訴321-1": ("刑訴法","321条1項","被告人以外の者の供述書・供述録取書","被告人以外の者が作成した供述書又はその者の供述を録取した書面で<mark>供述者の署名若しくは押印のあるもの</mark>は、次に掲げる場合に限り、これを証拠とすることができる。<br>一　裁判官の面前（第百五十七条の六第一項及び第二項に規定する方法による場合を含む。）における供述を録取した書面については、その供述者が死亡、精神若しくは身体の故障、所在不明若しくは国外にいるため公判準備若しくは公判期日において供述することができないとき、又は供述者が公判準備若しくは公判期日において前の供述と異なつた供述をしたとき。<br>二　検察官の面前における供述を録取した書面については、その供述者が死亡、精神若しくは身体の故障、所在不明若しくは国外にいるため公判準備若しくは公判期日において供述することができないとき、又は<mark>公判準備若しくは公判期日において前の供述と相反するか若しくは実質的に異なつた供述をしたとき</mark>。ただし、<mark>公判準備又は公判期日における供述よりも前の供述を信用すべき特別の情況の存するときに限る</mark>。<br>三　前二号に掲げる書面以外の書面については、供述者が死亡、精神若しくは身体の故障、所在不明又は国外にいるため公判準備又は公判期日において供述することができず、かつ、その供述が犯罪事実の存否の証明に欠くことができないものであるとき。ただし、その供述が特に信用すべき情況の下にされたものであるときに限る。"),
"訴321-3": ("刑訴法","321条3項","検証調書","<mark>検察官、検察事務官又は司法警察職員</mark>の検証の結果を記載した書面は、その供述者が公判期日において証人として尋問を受け、<mark>その真正に作成されたものであることを供述</mark>したときは、第一項の規定にかかわらず、これを証拠とすることができる。"),
"訴321-4": ("刑訴法","321条4項","鑑定書","<mark>鑑定の経過及び結果を記載した書面で鑑定人の作成したもの</mark>についても、前項と同様である。"),
"訴322": ("刑訴法","322条","被告人の供述書・供述録取書","1　<mark>被告人が作成した供述書又は被告人の供述を録取した書面</mark>で被告人の署名若しくは押印のあるものは、その供述が被告人に不利益な事実の承認を内容とするものであるとき、又は特に信用すべき情況の下にされたものであるときに限り、これを証拠とすることができる。但し、被告人に不利益な事実の承認を内容とする書面は、その承認が自白でない場合においても、第三百十九条の規定に準じ、任意にされたものでない疑があると認めるときは、これを証拠とすることができない。<br>2　被告人の公判準備又は公判期日における供述を録取した書面は、その供述が任意にされたものであると認めるときに限り、これを証拠とすることができる。"),
"訴324": ("刑訴法","324条","伝聞供述","1　被告人以外の者の公判準備又は公判期日における供述で<mark>被告人の供述をその内容とするもの</mark>については、第三百二十二条の規定を準用する。<br>2　被告人以外の者の公判準備又は公判期日における供述で被告人以外の者の供述をその内容とするものについては、第三百二十一条第一項第三号の規定を準用する。"),
"訴326": ("刑訴法","326条1項","同意書面","検察官及び被告人が証拠とすることに同意した書面又は供述は、その書面が作成され又は供述のされたときの情況を考慮し相当と認めるときに限り、第三百二十一条乃至前条の規定にかかわらず、これを証拠とすることができる。"),
"訴429": ("刑訴法","429条1項（抄）","準抗告","裁判官が左の裁判をした場合において、不服がある者は、簡易裁判所の裁判官がした裁判に対しては管轄地方裁判所に、その他の裁判官がした裁判に対してはその裁判官所属の裁判所にその裁判の取消又は変更を請求することができる。<br>…<br>二　<mark>勾留、保釈、押収又は押収物の還付に関する裁判</mark>（以下略）"),
"規187": ("刑訴規則","187条1項","勾留に関する処分をすべき裁判官","公訴の提起があつた後第一回の公判期日までの勾留に関する処分は、公訴の提起を受けた裁判所の裁判官がこれをしなければならない。但し、<mark>事件の審判に関与すべき裁判官は、その処分をすることができない</mark>。"),
"規189-2": ("刑訴規則","189条の2","証拠の厳選","証拠調べの請求は、証明すべき事実の立証に必要な証拠を<mark>厳選して</mark>、これをしなければならない。"),
"規199-3": ("刑訴規則","199条の3第3項","主尋問と誘導尋問","主尋問においては、<mark>誘導尋問をしてはならない</mark>。ただし、次の場合には、誘導尋問をすることができる。<br>一　証人の身分、経歴、交友関係等で、実質的な尋問に入るに先だつて明らかにする必要のある準備的な事項に関するとき。<br>二　訴訟関係人に争のないことが明らかな事項に関するとき。<br>三　<mark>証人の記憶が明らかでない事項についてその記憶を喚起するため必要があるとき</mark>。<br>四　証人が主尋問者に対して敵意又は反感を示すとき。<br>五　証人が証言を避けようとする事項に関するとき。<br>六　<mark>証人が前の供述と相反するか又は実質的に異なる供述をした場合</mark>において、その供述した事項に関するとき。<br>七　その他誘導尋問を必要とする特別の事情があるとき。"),
"規205": ("刑訴規則","205条","異議申立の事由","1　法第三百九条第一項の異議の申立は、法令の違反があること又は相当でないことを理由としてこれをすることができる。但し、<mark>証拠調に関する決定に対しては、相当でないことを理由としてこれをすることはできない</mark>。<br>2　法第三百九条第二項の異議の申立は、法令の違反があることを理由とする場合に限りこれをすることができる。"),
"規208": ("刑訴規則","208条1項","釈明","裁判長は、必要と認めるときは、訴訟関係人に対し、<mark>釈明を求め、又は立証を促す</mark>ことができる。"),
"職5": ("職務基本規程","5条","信義誠実","弁護士は、<mark>真実を尊重し</mark>、信義に従い、誠実かつ公正に職務を行うものとする。"),
"職14": ("職務基本規程","14条","違法行為の助長","弁護士は、詐欺的取引、暴力その他<mark>違法若しくは不正な行為を助長し</mark>、又はこれらの行為を利用してはならない。"),
"職22": ("職務基本規程","22条1項","依頼者の意思の尊重","弁護士は、委任の趣旨に関する<mark>依頼者の意思を尊重</mark>して職務を行うものとする。"),
"職23": ("職務基本規程","23条","秘密の保持","弁護士は、正当な理由なく、依頼者について職務上知り得た秘密を他に漏らし、又は利用してはならない。"),
"職25": ("職務基本規程","25条","依頼者との金銭貸借等","弁護士は、<mark>特別の事情がない限り</mark>、依頼者と金銭の貸借をし、又は自己の債務について依頼者に保証を依頼し、若しくは依頼者の債務について保証をしてはならない。"),
"職28": ("職務基本規程","28条","職務を行い得ない事件","弁護士は、前条に規定するもののほか、次の各号のいずれかに該当する事件については、その職務を行ってはならない。ただし、第一号及び第四号に掲げる事件についてその依頼者が同意した場合、第二号に掲げる事件についてその依頼者及び相手方が同意した場合並びに<mark>第三号に掲げる事件についてその依頼者及び他の依頼者のいずれもが同意した場合</mark>は、この限りでない。<br>一　相手方が配偶者、直系血族、兄弟姉妹又は同居の親族である事件<br>二　受任している他の事件の依頼者又は継続的な法律事務の提供を約している者を相手方とする事件<br>三　<mark>依頼者の利益と他の依頼者の利益が相反する事件</mark><br>四　依頼者の利益と自己の経済的利益が相反する事件"),
"職32": ("職務基本規程","32条","不利益事項の説明","弁護士は、同一の事件について複数の依頼者があってその相互間に利害の対立が生じるおそれがあるときは、事件を受任するに当たり、依頼者それぞれに対し、<mark>辞任の可能性その他の不利益を及ぼすおそれのあることを説明</mark>しなければならない。"),
"職42": ("職務基本規程","42条","受任後の利害対立","弁護士は、複数の依頼者があって、その相互間に利害の対立が生じるおそれのある事件を受任した後、依頼者相互間に<mark>現実に利害の対立が生じたとき</mark>は、依頼者それぞれに対し、速やかに、その事情を告げて、<mark>辞任その他の事案に応じた適切な措置</mark>をとらなければならない。"),
"職46": ("職務基本規程","46条","刑事弁護の心構え","弁護士は、被疑者及び被告人の防御権が保障されていることにかんがみ、その権利及び利益を擁護するため、<mark>最善の弁護活動</mark>に努める。"),
"職75": ("職務基本規程","75条","偽証のそそのかし","弁護士は、<mark>偽証若しくは虚偽の陳述をそそのかし</mark>、又は虚偽と知りながらその証拠を提出してはならない。"),
}
